// Generates supabase/migrations/0003_seed_lessons.sql from the lesson definitions so the
// database's published step lists can never drift from the code. Run: npm run gen:seed
import { writeFileSync } from 'node:fs';
import { LESSONS } from '../src/lessons/index.js';

const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const arr = (a) => `array[${a.map(q).join(', ')}]::text[]`;
const out = [
  '-- GENERATED by scripts/gen-seed.mjs — do not edit by hand.',
  `insert into public.modules (slug, position, published) values ('first-step', 1, true) on conflict (slug) do nothing;`,
];
let prev = null;
for (const { def } of [...LESSONS].sort((a, b) => a.def.order - b.def.order)) {
  out.push(
    `insert into public.lessons (slug, module_slug, position, prerequisite_slug, published) values (${q(def.id)}, 'first-step', ${def.order}, ${prev ? q(prev) : 'null'}, true) on conflict (slug) do nothing;`,
    `insert into public.lesson_versions (lesson_slug, version, step_ids, competencies, published) values (${q(def.id)}, ${def.version}, ${arr(def.steps.map((s) => s.id))}, ${arr(def.competencies)}, true) on conflict (lesson_slug, version) do nothing;`,
  );
  prev = def.id;
}
writeFileSync(new URL('../supabase/migrations/0003_seed_lessons.sql', import.meta.url), out.join('\n') + '\n');
console.log('wrote 0003_seed_lessons.sql');
